def solve(n, squares):
    g=[[0]*n for _ in range(n)]
    def S(r0,c0,s):
        for i in range(s):
            g[r0+i][c0]=5; g[r0+i][c0+s-1]=5; g[r0][c0+i]=5; g[r0+s-1][c0+i]=5
        if s>=3:
            for i in range(s-2):
                g[r0+1+i][c0+1]=2; g[r0+1+i][c0+s-2]=2; g[r0+1][c0+1+i]=2; g[r0+s-2][c0+1+i]=2
        if s>=5:  # inset2 ring/square = 5 (solid if small)
            for i in range(max(s-4,1)):
                g[r0+2+i][c0+2]=5; g[r0+2+i][c0+s-3]=5; g[r0+2][c0+2+i]=5; g[r0+s-3][c0+2+i]=5
        m = s-6  # interior side
        if m>=4: # nested side m-2 centered
            S(r0+4, c0+4, m-2)
    for (r0,c0,s) in squares: S(r0,c0,s)
    return g

